1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Sets the owner's {@code capacityWarning} flag to true when its city is approaching the
9	 * per-city capacity limit — the city already holds between {@value #WARN_LOW} and
10	 * {@value #WARN_HIGH} owners (the hard limit enforced by {@link EnsureCityCapacity} being
11	 * {@value EnsureCityCapacity#CAPACITY}), otherwise false. Counts all owners in the city
12	 * including this one, so the flag is identical whether returned from the create response
13	 * (runs after Save, so the new owner is counted) or a later GET, mirroring
14	 * {@link AssignOwnerBulkSignupWarning}.
15	 */
16	public class AssignOwnerCapacityWarning {
17	
18	    /** Lowest owners-in-city count (inclusive) that raises the approaching-capacity warning. */
19	    static final int WARN_LOW = 40;
20	
21	    /** Highest owners-in-city count (inclusive) that raises the approaching-capacity warning. */
22	    static final int WARN_HIGH = EnsureCityCapacity.CAPACITY - 1;
23	
24	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
25	        String city = owner.getCity();
26	        long count = ownerRepository.findAll().stream()
27	                .filter(o -> city == null ? o.getCity() == null : city.equals(o.getCity()))
28	                .count();
29	        owner.setCapacityWarning(count >= WARN_LOW && count <= WARN_HIGH);
30	    }
31	}
